import { useEffect, useState } from "react";
import { apiPost } from "../lib/apiClient";
import { useCheckoutStore } from "../store/useCheckoutStore";
import { useCartTotal } from "../hooks/useCartTotal";
import { useSubmitGuard } from "../hooks/useSubmitGuard";
import { t } from "../i18n/checkout";
import type { QuoteResponse } from "../types/checkout";

function normalizeCoupon(raw: string): string {
  return raw.trim().toUpperCase().slice(0, 8);
}

// Coupon input with live quote preview.
export default function CheckoutCouponInput() {
  const cartTotal = useCartTotal();
  const price_minor = useCheckoutStore((s) => s.price_minor);
  const couponCode = useCheckoutStore((s) => s.couponCode);
  const setCouponCode = useCheckoutStore((s) => s.setCouponCode);
  const setQuote = useCheckoutStore((s) => s.setQuote);
  const items = useCheckoutStore((s) => s.items);
  const address = useCheckoutStore((s) => s.address);
  const [draft, setDraft] = useState(couponCode);
  const { guard, release, locked } = useSubmitGuard({ timeoutMs: 8000, key: "place-order" });

  useEffect(() => {
    let cancelled = false;
    async function preview() {
      if (!draft) return;
      if (!guard()) return;
      try {
        const quote = await apiPost<QuoteResponse>("/api/checkout/quote", {
          items,
          address,
          coupon_code: draft
        });
        if (!cancelled) setQuote(quote);
      } catch {
        // Preview failure keeps the previous quote on screen.
      } finally {
        release();
      }
    }
    void preview();
    return () => {
      cancelled = true;
    };
  }, [cartTotal, price_minor, couponCode, draft, address, items, guard, release, setQuote]);

  return (
    <div>
      <label htmlFor="coupon">{t("checkout.coupon.label")}</label>
      <input
        id="coupon"
        value={draft}
        placeholder={t("checkout.coupon.placeholder")}
        onChange={(e) => setDraft(normalizeCoupon(e.target.value))}
        onBlur={() => setCouponCode(draft)}
        disabled={locked}
      />
    </div>
  );
}

