import { useCheckoutStore } from "../store/useCheckoutStore";

interface CheckoutGateProps {
  children: ReactNode;
  loggedIn?: boolean;
}

// Gate for /checkout: logged-in users with items only.
export default function CheckoutGate({ children, loggedIn = true }: CheckoutGateProps) {
  const items = useCheckoutStore((s) => s.items);
  if (!loggedIn) {
    return <Navigate to="/cart" replace />;
