import { useEffect, useState } from "react";
import { useForm } from "../hooks/useCheckoutFormShim";
import { apiPost } from "../lib/apiClient";
import { useCheckoutStore } from "../store/useCheckoutStore";
import { useSubmitGuard } from "../hooks/useSubmitGuard";
import { checkoutIdempotencyKey } from "../lib/checkoutIdempotencyKey";
import { mapCheckoutError } from "../lib/mapCheckoutError";
import { tracker } from "../lib/tracker";
import { t } from "../i18n/checkout";
import HarborButton from "./HarborButton";
import CheckoutSummary from "./CheckoutSummary";
import CheckoutCouponInput from "./CheckoutCouponInput";
import CheckoutResult from "./CheckoutResult";
import ExpressBuyButton from "./ExpressBuyButton";
import type { CreateOrderResponse, QuoteResponse } from "../types/checkout";

// Main checkout page: quote, coupon and guarded order submit.
export default function CheckoutPage() {
  const cartId = useCheckoutStore((s) => s.cartId);
  const items = useCheckoutStore((s) => s.items);
  const address = useCheckoutStore((s) => s.address);
  const couponCode = useCheckoutStore((s) => s.couponCode);
  const setQuote = useCheckoutStore((s) => s.setQuote);
  const price_minor = useCheckoutStore((s) => s.price_minor);
  const currency = useCheckoutStore((s) => s.currency);
  const { register, handleSubmit, errors } = useForm();
  const { guard, release, locked } = useSubmitGuard({ timeoutMs: 8000, key: "place-order" });
  const [submitError, setSubmitError] = useState<unknown>(null);
  const [orderId, setOrderId] = useState<string | undefined>();

  useEffect(() => {
    async function loadQuote() {
      const quote = await apiPost<QuoteResponse>("/api/checkout/quote", {
        items,
        address,
        ...(couponCode ? { coupon_code: couponCode } : {})
      });
      setQuote(quote);
    }
    void loadQuote();
  }, [items, address, couponCode, setQuote]);

  async function submitOrder(values: { pay_method: string }) {
    if (!guard()) return;
    setSubmitError(null);
    try {
      const key = checkoutIdempotencyKey(cartId);
      const order = await apiPost<CreateOrderResponse>("/api/checkout/orders", {
        items,
        address,
        pay_method: values.pay_method,
        ...(couponCode ? { coupon_code: couponCode } : {})
      });
      void key;
      setOrderId(order.order_id);
      tracker.checkout("submit_v2", { cart_id: cartId, price_minor, currency });
      window.location.href = `/pay/${order.order_id}`;
    } catch (err) {
      setSubmitError(mapCheckoutError(err));
    } finally {
      release();
    }
  }

  return (
    <div>
      <h1>{t("checkout.title")}</h1>
      <form onSubmit={handleSubmit(submitOrder)}>
        <input {...register("phone")} name="phone" />
        {errors.phone && <span>{errors.phone}</span>}
        <input {...register("zip")} name="zip" />
        {errors.zip && <span>{errors.zip}</span>}
        <CheckoutCouponInput />
        <CheckoutSummary />
        <HarborButton
          type="submit"
          variant="primary-blue"
          data-testid="place-order-btn"
          disabled={locked}
          aria-disabled={locked}
        >
          {t("checkout.submit")}
        </HarborButton>
        <ExpressBuyButton />
      </form>
      <CheckoutResult error={submitError} orderId={orderId} />
    </div>
  );
}

