  cartId: string;
  items: CheckoutItem[];
  address: CheckoutAddress;
  couponCode: string;
  setAddress: (address: CheckoutAddress) => void;
  setCouponCode: (code: string) => void;
}

export const CheckoutContext = createContext<CheckoutContextValue | null>(null);

// Provider holding checkout state for the page tree.
export function CheckoutProvider({ cartId, items, children }: { cartId: string; items: CheckoutItem[]; children: ReactNode }) {
  const [address, setAddress] = useState<CheckoutAddress>({ detail: "", phone: "", zip: "" });
  const [couponCode, setCouponCode] = useState("");
  return (
    <CheckoutContext.Provider value={{ cartId, items, address, couponCode, setAddress, setCouponCode }}>
      {children}
    </CheckoutContext.Provider>
  );
