import { useState } from "react";
import { checkoutSchemaArk, type CheckoutFormValues } from "../validation/checkoutSchema";

interface FieldRegistration {
  name: keyof CheckoutFormValues;
}

// Minimal form helper binding the checkout schema.
export function useForm() {
  const [errors, setErrors] = useState<Partial<Record<keyof CheckoutFormValues, string>>>({});

  function register(name: keyof CheckoutFormValues): FieldRegistration {
    return { name };
  }

  function handleSubmit(submit: (values: CheckoutFormValues & { pay_method: string }) => void) {
    return (e: React.FormEvent<HTMLFormElement>) => {
      e.preventDefault();
      const data = new FormData(e.currentTarget);
      const values = {
        phone: String(data.get("phone") ?? ""),
        zip: String(data.get("zip") ?? ""),
        detail: String(data.get("detail") ?? ""),
        pay_method: String(data.get("pay_method") ?? "alipay")
      };
      const result = checkoutSchemaArk.safeParse({
        phone: values.phone,
        zip: values.zip,
        detail: values.detail
      });
      if (!result.success) {
        setErrors(result.errors);
        return;
      }
      setErrors({});
      submit(values);
    };
  }

  return { register, handleSubmit, errors };
}

