const STORAGE_KEY = "harbor:checkout:idem";

function newUuid(): string {
  if (typeof crypto !== "undefined" && "randomUUID" in crypto) {
    return crypto.randomUUID();
  }
  return `uuid-${Date.now()}-${Math.floor(Math.random() * 1e9)}`;
}

interface StoredKey {
  cartId: string;
  key: string;
}

function readStored(): StoredKey | null {
  try {
    const raw = sessionStorage.getItem(STORAGE_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw) as StoredKey;
    if (!parsed.cartId || !parsed.key) return null;
    return parsed;
  } catch {
    return null;
  }
}

// Return the fixed idempotency key for one cart.
export function checkoutIdempotencyKey(cartId: string): string {
  const stored = readStored();
  if (stored && stored.cartId === cartId) {
    return stored.key;
  }
  const key = newUuid();
  try {
    sessionStorage.setItem(STORAGE_KEY, JSON.stringify({ cartId, key }));
  } catch {
    // Storage unavailable; caller still gets a key for this attempt.
  }
  return key;
}

// Create the key once when checkout starts.
export function initCheckoutIdempotency(cartId: string): string {
  return checkoutIdempotencyKey(cartId);
}

