import type { Currency } from "../types/checkout";

const symbols: Record<Currency, string> = {
  CNY: "¥",
  USD: "$",
  EUR: "€"
};

// Render a minor-unit amount with its currency.
export function formatMoney(price_minor: number, currency: Currency): string {
  const safe = Number.isFinite(price_minor) && price_minor > 0 ? Math.round(price_minor) : 0;
  const major = (safe / 100).toFixed(2);
  const symbol = symbols[currency] ?? "";
  return `${symbol}${major}`;
}

