import { t } from "../i18n/checkout";

function codeOf(err: unknown): string {
  if (typeof err === "object" && err !== null) {
    const record = err as Record<string, unknown>;
    if (typeof record.code === "string") return record.code;
    const body = record.body as Record<string, unknown> | undefined;
    if (body && typeof body.code === "string") return body.code;
  }
  if (err instanceof Error) return err.message;
  return String(err);
}

// Map backend error codes to display copy.
export function mapCheckoutError(err: unknown): string {
  const code = codeOf(err);
  switch (code) {
    case "INSUFFICIENT_STOCK":
      return t("checkout.errors.insufficient_stock");
    case "PAY_GATEWAY_502":
      return t("checkout.errors.pay_busy");
    case "INVALID_COUPON":
      return t("checkout.errors.invalid_coupon");
    case "E_ADDR_ZIP":
      return t("checkout.errors.E_ADDR_ZIP");
    case "E_PHONE_FMT":
      return t("checkout.errors.E_PHONE_FMT");
    default:
      return t("checkout.errors.bad_request");
  }
}

