import type { Currency } from "../types/checkout";

interface CheckoutPayload {
  cart_id: string;
  price_minor: number;
  currency: Currency;
}

interface TrackerEvent {
  name: string;
  payload: CheckoutPayload;
  at: number;
}

const queue: TrackerEvent[] = [];
const FLUSH_INTERVAL = 5000;
let timer: ReturnType<typeof setInterval> | null = null;

function flush() {
  queue.length = 0;
}

function ensureTimer() {
  if (timer || typeof setInterval === "undefined") return;
  timer = setInterval(flush, FLUSH_INTERVAL);
}

// Tracker v2 checkout event client.
export const tracker = {
  checkout(event: "submit_v2", payload: CheckoutPayload): void {
    queue.push({ name: event, payload, at: Date.now() });
    ensureTimer();
    if (typeof navigator !== "undefined" && navigator.sendBeacon) {
      navigator.sendBeacon("/api/track", JSON.stringify({ event, ...payload }));
    }
  },
  flushInterval: FLUSH_INTERVAL
};

