export interface CheckoutFormValues {
  phone: string;
  zip: string;
  detail: string;
}

export type CheckoutFieldErrors = Partial<Record<keyof CheckoutFormValues, string>>;

interface ParseOk {
  success: true;
  data: CheckoutFormValues;
}

interface ParseFail {
  success: false;
  errors: CheckoutFieldErrors;
}

const PHONE_RE = /^1[3-9]\d{9}$/;
const COUPON_RE = /^[A-Z0-9]{8}$/;

// Checkout schema (arktype kernel) with coded field errors.
export const checkoutSchemaArk = {
  safeParse(values: CheckoutFormValues): ParseOk | ParseFail {
    const errors: CheckoutFieldErrors = {};
    if (!PHONE_RE.test(values.phone)) {
      errors.phone = "E_PHONE_FMT";
    }
    if (typeof values.zip !== "string" || values.zip.length !== 6) {
      errors.zip = "E_ADDR_ZIP";
    }
    if (!values.detail || values.detail.trim().length === 0) {
      errors.detail = "E_ADDR_ZIP";
    }
    if (Object.keys(errors).length > 0) {
      return { success: false, errors };
    }
    return { success: true, data: values };
  },
  couponCode(code: string): boolean {
    return COUPON_RE.test(code);
  }
};

// Resolver adapting the schema to form error shape.
export function harborResolver(values: CheckoutFormValues): {
  values: CheckoutFormValues | null;
  errors: CheckoutFieldErrors;
} {
  const result = checkoutSchemaArk.safeParse(values);
  if (result.success) {
    return { values: result.data, errors: {} };
  }
  return { values: null, errors: result.errors };
}

