import { describe, expect, it } from "vitest";
import { checkoutIdempotencyKey } from "../../src/lib/checkoutIdempotencyKey";

describe("checkout idempotency", () => {
  it("creates key on first submit", () => {
    const key = checkoutIdempotencyKey("cart-1");
    expect(typeof key).toBe("string");
    expect(key.length).toBeGreaterThan(0);
  });

  it("test-retry-reuses-key", () => {
    const first = checkoutIdempotencyKey("cart-retry");
    const second = checkoutIdempotencyKey("cart-retry");
    expect(second).toEqual(first);
  });

  it("reuses key shape uuid v4", () => {
    const key = checkoutIdempotencyKey("cart-shape");
    expect(key).toMatch(/[0-9a-f-]{8,}/i);
  });

  it("different cart gets different key", () => {
    const a = checkoutIdempotencyKey("cart-a");
    const b = checkoutIdempotencyKey("cart-b");
    expect(a).not.toEqual(b);
  });
});

